import{ENCADRES,LIMITES,NOMS_ENCADRES,RE_CIBLE}from"./chunk-VB33RMAF.js";import{lien}from"./chunk-MENTKLMX.js";var coupe=(t,max)=>String(t??"").slice(0,max);function texteGras(el,t,max){let morceaux=coupe(t,max).split("**");return morceaux.forEach((m,i)=>{if(m)if(i%2===1&&i<morceaux.length-1){let b=document.createElement("strong");b.textContent=m,el.appendChild(b)}else el.appendChild(document.createTextNode(i%2===1?"**"+m:m))}),el}function element(nom,classe){let el=document.createElement(nom);return classe&&(el.className=classe),el}function bloc(b,opts){if(!b||typeof b!="object")return null;switch(b.type){case"titre":{let h=element("h"+opts.niveau);return h.textContent=coupe(b.texte,LIMITES.titre),h}case"paragraphe":return texteGras(element("p"),b.texte,LIMITES.paragraphe);case"liste":{let ul=element("ul");return(Array.isArray(b.items)?b.items:[]).slice(0,LIMITES.items).forEach(x=>ul.appendChild(texteGras(element("li"),x,LIMITES.item))),ul.childNodes.length?ul:null}case"lien":{let p=element("p","page-lien"),cible=String(b.cible||""),texte=coupe(b.texte,LIMITES.lien)||cible;if(!RE_CIBLE.test(cible))return p.textContent=texte,p;let a=element("a");return a.href=lien(cible),a.textContent=texte,opts.ailleurs&&(a.target="_blank",a.rel="noopener"),p.appendChild(a),p}case"encadre":{let sorte=ENCADRES.includes(b.sorte)?b.sorte:"info",d=element("aside","encadre "+sorte),s=element("strong");return s.textContent=NOMS_ENCADRES[sorte],d.appendChild(s),d.appendChild(texteGras(element("p"),b.texte,LIMITES.encadre)),d}}return null}function rendreBlocs(blocs,opts){let o=Object.assign({niveau:2,ailleurs:!1},opts||{}),frag=document.createDocumentFragment();return(Array.isArray(blocs)?blocs:[]).slice(0,LIMITES.blocs).forEach(b=>{let el=bloc(b,o);el&&frag.appendChild(el)}),frag}export{rendreBlocs};
